/**
 * Copies db/migrations/*.sql into src/server/migrations.generated.ts.
 *
 * The app carries its schema inside its own code, so creating the tables
 * never depends on where the host runs the app from or which files it
 * copies. Runs automatically before every build (`prebuild`); the output is
 * also committed. Edit the .sql files, never the generated file.
 */
import { readdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const dir = join(root, "db", "migrations");
const files = readdirSync(dir).filter((f) => f.endsWith(".sql")).sort();

const body = files
  .map((f) => `  { version: ${JSON.stringify(f)}, sql: ${JSON.stringify(readFileSync(join(dir, f), "utf8"))} },`)
  .join("\n");

writeFileSync(
  join(root, "src", "server", "migrations.generated.ts"),
  `// GENERATED by scripts/bundle-migrations.mjs from db/migrations/*.sql — do not edit.\n` +
    `export const MIGRATIONS: { version: string; sql: string }[] = [\n${body}\n];\n`,
);
console.log(`Bundled ${files.length} migrations.`);
